// ENG-2256 relation menu empty state + add flyout, driven with real CDP mouse/key input.
const D = "_verify/eng-2360-document-canvas-relation-type-creation-for-unconfigured-node";
const CANVAS = `${D}/Sleep and memory.md`;
const Q = "shape:verify-vqZxA";
const C = "shape:verify-bqu6_";
const E = "shape:verify-4dCoS";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export const prepare = async ({ client, json }, cam = { x: 150, y: 150, z: 0.8 }) => {
  await client.evaluate(`return (async () => {
    let leaf = app.workspace.getLeavesOfType("tldraw-dg-preview").find((l) => l.view.file?.path === ${json(CANVAS)});
    if (!leaf) {
      leaf = app.workspace.getLeaf("tab");
      await leaf.setViewState({ type: "tldraw-dg-preview", state: { file: ${json(CANVAS)} } });
    }
    app.workspace.setActiveLeaf(leaf, { focus: true });
    await new Promise((r) => setTimeout(r, 400));
    const el = leaf.view.containerEl.querySelector(".tl-canvas");
    const k = Object.keys(el).find((k) => k.startsWith("__reactFiber"));
    let f = el[k];
    while (f) { const v = f.memoizedProps?.value; if (v?.store && v.getCurrentPageShapes) { window.__dgEd = v; break; } f = f.return; }
    const ed = window.__dgEd;
    ed.deleteShapes(ed.getCurrentPageShapes().filter((s) => s.type === "discourse-relation").map((s) => s.id));
    // Deleting a pending arrow dismisses its menu, which reselects the source node in an effect.
    await new Promise((r) => setTimeout(r, 400));
    ed.selectNone();
    ed.setCamera(${json(cam)});
    if (!window.__dgToastHook) {
      window.__dgToastHook = true;
      document.addEventListener("show-toast", (e) => (window.__dgToasts ??= []).push(e.detail.description ?? e.detail.title));
    }
    window.__dgToasts = [];
    return true;
  })();`);
};

const mouse = (client, type, x, y, extra = {}) =>
  client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1, ...extra });

const clickAt = async (client, { x, y }) => {
  await mouse(client, "mouseMoved", x, y, { button: "none" });
  await mouse(client, "mousePressed", x, y, { buttons: 1 });
  await mouse(client, "mouseReleased", x, y);
  await sleep(250);
};

// Select `from`, press on the drag dot nearest `to`, move in steps to `to`'s center, release.
export const dragRelation = async ({ client, json }, from, to) => {
  await client.evaluate(`window.__dgEd.select(${json(from)}); return true;`);
  await sleep(300);
  const sel = await client.evaluate(`return window.__dgEd.getSelectedShapeIds();`);
  if (sel.length !== 1 || sel[0] !== from) throw new Error(`expected ${from} selected, got ${sel}`);
  const pts = await client.evaluate(`
    const ed = window.__dgEd;
    const b = ed.getShapePageBounds(${json(to)});
    const target = ed.pageToScreen({ x: b.midX, y: b.midY });
    const dots = [...ed.getContainer().querySelectorAll(".cursor-crosshair")].map((d) => {
      const r = d.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    });
    dots.sort((a, c) => Math.hypot(a.x - target.x, a.y - target.y) - Math.hypot(c.x - target.x, c.y - target.y));
    return { start: dots[0], target, dotCount: dots.length };`);
  if (!pts.start) throw new Error("no drag handle dots rendered");
  const { start, target } = pts;
  await mouse(client, "mouseMoved", start.x, start.y, { button: "none" });
  await mouse(client, "mousePressed", start.x, start.y, { buttons: 1 });
  for (let i = 1; i <= 12; i++) {
    const t = i / 12;
    await mouse(client, "mouseMoved", start.x + (target.x - start.x) * t, start.y + (target.y - start.y) * t, { buttons: 1 });
    await sleep(20);
  }
  await mouse(client, "mouseReleased", target.x, target.y);
  await sleep(400);
  return pts;
};

// Snapshot of the menu, flyout, pending arrow and toasts.
export const observe = ({ client }) =>
  client.evaluate(`
    const ed = window.__dgEd;
    const header = [...document.querySelectorAll("span")].find((s) => s.textContent.trim().toLowerCase() === "relation type");
    const root = header?.closest(".pointer-events-auto");
    const rect = (el) => { if (!el) return null; const r = el.getBoundingClientRect(); return { l: Math.round(r.left), t: Math.round(r.top), r: Math.round(r.right), b: Math.round(r.bottom), w: Math.round(r.width), h: Math.round(r.height) }; };
    const menu = root?.children[0];
    const flyout = root?.children[1] ?? null;
    const plus = root?.querySelector('[aria-label="Add relation type"]');
    const svg = plus?.querySelector("svg");
    const arrows = ed.getCurrentPageShapes().filter((s) => s.type === "discourse-relation");
    const a = arrows[0];
    const binds = a ? ed.getBindingsFromShape(a.id, "discourse-relation").map((b) => b.props.terminal + ":" + b.toId) : [];
    return {
      menuOpen: !!root,
      menuItems: menu ? [...menu.querySelectorAll(":scope > button")].map((b) => b.textContent.trim()) : [],
      plus: plus ? { expanded: plus.getAttribute("aria-expanded"), hasSvg: !!svg, svgClass: svg?.getAttribute("class"), svgRect: rect(svg), btnRect: rect(plus) } : null,
      headerRect: rect(header?.parentElement),
      menuRect: rect(menu),
      flyout: flyout ? { items: [...flyout.querySelectorAll("button")].map((b) => b.textContent.trim()), rect: rect(flyout) } : null,
      arrowCount: arrows.length,
      arrow: a ? { relationTypeId: a.props.relationTypeId, color: a.props.color, text: a.props.text, bindings: binds, relationInstanceId: a.meta?.relationInstanceId ?? null } : null,
      toasts: window.__dgToasts ?? [],
      selected: ed.getSelectedShapeIds(),
    };`);

const buttonCenter = ({ client, json }, label, where = "any") =>
  client.evaluate(`
    const header = [...document.querySelectorAll("span")].find((s) => s.textContent.trim().toLowerCase() === "relation type");
    const root = header?.closest(".pointer-events-auto");
    const scope = ${json(where)} === "flyout" ? root?.children[1] : ${json(where)} === "menu" ? root?.children[0] : root;
    const btn = ${json(label)} === "+" ? root?.querySelector('[aria-label="Add relation type"]')
      : [...(scope?.querySelectorAll("button") ?? [])].find((b) => b.textContent.trim() === ${json(label)});
    if (!btn) return null;
    const r = btn.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);

export const clickButton = async (ctx, label, where) => {
  const p = await buttonCenter(ctx, label, where);
  if (!p) throw new Error(`button ${label} (${where}) not found`);
  await clickAt(ctx.client, p);
};

const ADD = ["Add existing…", "Create new"];
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const bothBound = (o) => o.arrow?.bindings.some((b) => b.startsWith("start:")) && o.arrow?.bindings.some((b) => b.startsWith("end:"));

#####
// ENG-2360 docs screenshots: relation type menu empty state, + flyout, Add existing picker, Create new flow (GIF frames).
import fs from "node:fs";
import { prepare, clickButton, observe } from "./base.mjs";

const Q = "shape:verify-vqZxA";
const C = "shape:verify-bqu6_";
const E = "shape:verify-4dCoS";
const OUT = new URL("./shots/", import.meta.url).pathname;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const P = (ctx) => `app.plugins.plugins[${ctx.json(ctx.vault.pluginId)}]`;
const DIALOG = `[...document.querySelectorAll(".modal-container")].find((m) => m.querySelector(".modal-title")?.textContent.trim() === "Add relation type")`;

const dialog = (ctx) =>
  ctx.client.evaluate(`
    const m = ${DIALOG};
    if (!m) return { open: false };
    const inputs = [...m.querySelectorAll("input[type=text]")];
    return {
      open: true,
      placeholders: inputs.map((i) => i.placeholder),
      values: inputs.map((i) => i.value),
      invalid: inputs.map((i) => i.classList.contains("input-error")),
      error: m.querySelector(".text-error")?.textContent.trim() ?? null,
      color: m.querySelector(".relative.min-w-32 > button")?.textContent.replace(/[▲▼]/g, "").trim() ?? null,
      buttons: [...m.querySelectorAll(".modal-button-container button")].map((b) => b.textContent.trim()),
      focused: document.activeElement?.placeholder ?? document.activeElement?.tagName,
    };`);

const centerOf = async (ctx, js) => {
  const p = await ctx.client.evaluate(`const el = (() => { ${js} })(); if (!el) return null; const r = el.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);
  if (!p) throw new Error(`element not found: ${js}`);
  return p;
};
const clickAt = async (client, { x, y }) => {
  const m = (type, extra = {}) => client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1, ...extra });
  await m("mouseMoved", { button: "none" });
  await m("mousePressed", { buttons: 1 });
  await m("mouseReleased");
  await sleep(250);
};
const clickEl = async (ctx, js) => clickAt(ctx.client, await centerOf(ctx, js));
const clickInput = (ctx, i) => clickEl(ctx, `return ${DIALOG}?.querySelectorAll("input[type=text]")[${i}];`);
const clickDialogButton = (ctx, text) =>
  clickEl(ctx, `return [...(${DIALOG}?.querySelectorAll("button") ?? [])].find((b) => b.textContent.trim() === ${ctx.json(text)});`);
const colorOption = (ctx, name) =>
  `return [...(${DIALOG}?.querySelectorAll(".relative.min-w-32 > div button") ?? [])].find((b) => b.textContent.trim() === ${ctx.json(name)});`;

const openDialog = async (ctx, where) => {
  await clickButton(ctx, "Create new", where);
  await ctx.client.waitFor(`!!${DIALOG}`, { label: "Add relation type dialog" });
  await sleep(200);
};

// Types into the focused label input, then the complement; picks a colour when given.
const fillDialog = async (ctx, { label, complement, color }) => {
  if (label) {
    await clickInput(ctx, 0);
    await ctx.client.typeText(label);
  }
  if (complement) {
    await clickInput(ctx, 1);
    await ctx.client.typeText(complement);
  }
  if (color) {
    await clickEl(ctx, `return ${DIALOG}?.querySelector(".relative.min-w-32 > button");`);
    await clickEl(ctx, colorOption(ctx, color));
  }
};

const diskSettings = (ctx) =>
  ctx.client.evaluate(`return app.vault.adapter.read(${ctx.json(ctx.vault.pluginDir.replace(ctx.vault.root + "/", "") + "/data.json")}).then((t) => { const d = JSON.parse(t); return { relationTypes: d.relationTypes, discourseRelations: d.discourseRelations }; });`);

const pair = (ctx, from, to) =>
  ctx.client.evaluate(`const ed = window.__dgEd; return { s: ed.getShape(${ctx.json(from)}).props.nodeTypeId, t: ed.getShape(${ctx.json(to)}).props.nodeTypeId };`);

const snapshot = async (ctx) => ({
  relationsJson: await ctx.client.evaluate(`return app.vault.read(app.vault.getAbstractFileByPath("relations.json"));`),
  settings: await ctx.client.evaluate(`const s = ${P(ctx)}.settings; return JSON.stringify({ relationTypes: s.relationTypes, discourseRelations: s.discourseRelations });`),
});
const restore = async (ctx, state) => {
  await ctx.client.clearModals?.();
  await ctx.client.evaluate(`const ed = window.__dgEd; ed?.deleteShapes(ed.getCurrentPageShapes().filter((s) => s.type === "discourse-relation").map((s) => s.id)); return true;`);
  if (!state) return;
  await ctx.client.evaluate(`const p = ${P(ctx)}; Object.assign(p.settings, JSON.parse(${ctx.json(state.settings)})); return p.saveSettings().then(() => true);`);
  await ctx.client.evaluate(`return app.vault.modify(app.vault.getAbstractFileByPath("relations.json"), ${ctx.json(state.relationsJson)}).then(() => true);`);
};


// Tidy fixture, clean in-memory settings (restored in teardown), hide Obsidian notices.
const docsPrepare = async (ctx) => {
  await ctx.client.evaluate(`app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse(); return true;`);
  await prepare(ctx);
  await ctx.client.evaluate(`const st = ${P(ctx)}.settings;
    const keep = new Set(["supports", "opposes", "informs", "derived from"]);
    st.relationTypes = st.relationTypes.filter((r) => keep.has(r.label));
    const ids = new Set(st.relationTypes.map((r) => r.id));
    const q = ${ctx.json("node_vqZxAvvuf-AN9E5Y4kH-F")}, c = ${ctx.json("node_bqu6_78DrVvuDnqmc6QzS")};
    st.discourseRelations = st.discourseRelations.filter((r) => ids.has(r.relationshipTypeId) &&
      !((r.sourceId === q && r.destinationId === c) || (r.sourceId === c && r.destinationId === q)));
    const ed = window.__dgEd;
    ed.deleteShapes(ed.getCurrentPageShapes().filter((s) => s.type !== "discourse-node").map((s) => s.id));
    ed.updateShapes([
      { id: ${ctx.json(C)}, type: "discourse-node", x: 0, y: 0, rotation: 0 },
      { id: ${ctx.json(Q)}, type: "discourse-node", x: 760, y: 0, rotation: 0 },
      { id: ${ctx.json(E)}, type: "discourse-node", x: 0, y: 360, rotation: 0 },
    ]);
    ed.selectNone();
    const z = 0.8; ed.setCamera({ x: 70 / z, y: 90 / z, z }, { immediate: true });
    document.querySelectorAll(".notice").forEach((n) => n.remove());
    return true;`);
  await sleep(500);
};

const hideNotices = (ctx) => ctx.client.evaluate(`document.querySelectorAll(".notice").forEach((n) => n.remove()); return true;`);

// Canvas container rect (CSS px).
const clipRect = (ctx) =>
  ctx.client.evaluate(`const ed = window.__dgEd; const r = ed.getContainer().getBoundingClientRect();
    return { x: r.left, y: r.top, width: r.width, height: r.height };`);

// Clip to the canvas container (CSS px); captured at device scale.
const shot = async (ctx, name) => {
  await hideNotices(ctx);
  const r = await clipRect(ctx);
  const { data } = await ctx.client.send("Page.captureScreenshot", { format: "png", clip: { ...r, scale: 1 } });
  fs.writeFileSync(OUT + name, Buffer.from(data, "base64"));
  return name;
};

// Drag from the dot of `from` nearest `to`, capturing a frame every few steps when `frames` is given.
const drag = async (ctx, from, to, frames) => {
  const { client, json } = ctx;
  const m = (type, x, y, extra = {}) => client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1, ...extra });
  const c0 = await client.evaluate(`const ed = window.__dgEd; const b = ed.getShapePageBounds(${json(from)}); return ed.pageToScreen({ x: b.midX, y: b.midY });`);
  await m("mouseMoved", c0.x, c0.y, { button: "none" });
  await m("mousePressed", c0.x, c0.y, { buttons: 1 });
  await m("mouseReleased", c0.x, c0.y);
  await sleep(400);
  if (frames) await frames.add("select", 2);
  const { start, target } = await client.evaluate(`
    const ed = window.__dgEd;
    const b = ed.getShapePageBounds(${json(to)});
    const target = ed.pageToScreen({ x: b.midX, y: b.midY });
    const dots = [...ed.getContainer().querySelectorAll(".cursor-crosshair")].map((d) => {
      const r = d.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; });
    dots.sort((a, c) => Math.hypot(a.x - target.x, a.y - target.y) - Math.hypot(c.x - target.x, c.y - target.y));
    return { start: dots[0], target };`);
  if (!start) throw new Error("no drag dots");
  await m("mouseMoved", start.x, start.y, { button: "none" });
  await m("mousePressed", start.x, start.y, { buttons: 1 });
  const N = 16;
  for (let i = 1; i <= N; i++) {
    const t = i / N;
    await m("mouseMoved", start.x + (target.x - start.x) * t, start.y + (target.y - start.y) * t, { buttons: 1 });
    await sleep(25);
    if (frames && i % 3 === 0) await frames.add("drag", 0.12);
  }
  await m("mouseReleased", target.x, target.y);
  await sleep(500);
};

// Frame recorder: PNGs plus an ffmpeg concat list with per-frame durations (seconds).
const recorder = (name) => {
  const dir = `${OUT}${name}/`;
  fs.rmSync(dir, { recursive: true, force: true });
  fs.mkdirSync(dir, { recursive: true });
  let n = 0;
  const list = [];
  return {
    ctx: null,
    async add(_label, dur) {
      const f = `f${String(++n).padStart(3, "0")}.png`;
      await hideNotices(this.ctx);
      const r = await clipRect(this.ctx);
      const { data } = await this.ctx.client.send("Page.captureScreenshot", { format: "png", clip: { ...r, scale: 1 } });
      fs.writeFileSync(dir + f, Buffer.from(data, "base64"));
      list.push(`file '${f}'\nduration ${dur}`);
    },
    done() {
      const last = list[list.length - 1].split("\n")[0];
      fs.writeFileSync(dir + "list.txt", list.join("\n") + "\n" + last + "\n");
      return n;
    },
  };
};

const typeSlow = async (ctx, text, frames, every = 4) => {
  for (let i = 0; i < text.length; i++) {
    await ctx.client.typeText(text[i]);
    if (frames && (i % every === every - 1 || i === text.length - 1)) await frames.add("type", 0.1);
  }
};

const LABEL = "addresses";
const COMPLEMENT = "is addressed by";

export default [
  {
    name: "Empty relation type menu",
    input: "drag Claim → Question (no relation types for the pair)",
    expected: "menu shows Add existing… and Create new",
    setup: snapshot,
    run: async (ctx) => {
      await docsPrepare(ctx);
      await drag(ctx, C, Q);
      const o = await observe(ctx);
      await shot(ctx, "relation-type-menu-empty.png");
      return o;
    },
    expect: (o) => ({ pass: o.menuOpen && JSON.stringify(o.menuItems) === JSON.stringify(["Add existing…", "Create new"]), actual: o.menuItems.join(" / ") }),
    teardown: restore,
  },
  {
    name: "Populated menu with + flyout",
    input: "drag Evidence → Claim; click +",
    expected: "menu lists supports/opposes; flyout shows both actions",
    setup: snapshot,
    run: async (ctx) => {
      await docsPrepare(ctx);
      await drag(ctx, E, C);
      await clickButton(ctx, "+");
      await sleep(300);
      const o = await observe(ctx);
      await shot(ctx, "relation-type-menu-add.png");
      return o;
    },
    expect: (o) => ({ pass: o.menuOpen && !!o.flyout && o.flyout.items.length === 2, actual: `${o.menuItems.join("/")} | ${o.flyout?.items.join("/")}` }),
    teardown: restore,
  },
  {
    name: "Add existing picker then add",
    input: "drag Claim → Question; Add existing…; pick informs",
    expected: "picker lists 4 types; after pick, menu lists informs and toast shows",
    setup: snapshot,
    run: async (ctx) => {
      await docsPrepare(ctx);
      await drag(ctx, C, Q);
      await clickButton(ctx, "Add existing…", "menu");
      await sleep(400);
      const picker = await ctx.client.evaluate(`const header = [...document.querySelectorAll("span")].find((s) => s.textContent.trim().toLowerCase() === "relation type");
        return [...header.closest(".pointer-events-auto").querySelectorAll("button")].map((b) => b.textContent.trim());`);
      await shot(ctx, "relation-type-add-existing.png");
      await clickButton(ctx, "informs / is informed by");
      await sleep(700);
      const o = await observe(ctx);
      await shot(ctx, "relation-type-added.png");
      return { picker, ...o };
    },
    expect: (o) => ({ pass: o.picker.some((p) => p.startsWith("informs")) && o.menuItems.includes("informs") && o.toasts.length > 0, actual: `picker=[${o.picker}] menu=[${o.menuItems}] toasts=[${o.toasts}]` }),
    teardown: restore,
  },
  {
    name: "Create new flow (GIF frames)",
    input: `drag Claim → Question; Create new; "${LABEL}" / "${COMPLEMENT}" / Blue; Continue; click ${LABEL}`,
    expected: "dialog, both toasts, new type listed, arrow labelled",
    setup: snapshot,
    run: async (ctx) => {
      await docsPrepare(ctx);
      const fr = recorder("create-flow");
      fr.ctx = ctx;
      await fr.add("start", 1.2);
      await drag(ctx, C, Q, fr);
      await fr.add("menu", 1.8);
      await openDialog(ctx, "menu");
      await fr.add("dialog", 1.2);
      await clickInput(ctx, 0);
      await typeSlow(ctx, LABEL, fr);
      await clickInput(ctx, 1);
      await typeSlow(ctx, COMPLEMENT, fr);
      await clickEl(ctx, `return ${DIALOG}?.querySelector(".relative.min-w-32 > button");`);
      await fr.add("colors", 1.2);
      await clickEl(ctx, colorOption(ctx, "Blue"));
      await fr.add("filled", 1.5);
      await shot(ctx, "add-relation-type-dialog.png");
      await clickDialogButton(ctx, "Continue");
      await sleep(600);
      await fr.add("toasts", 2.5);
      const after = await observe(ctx);
      await shot(ctx, "relation-type-created.png");
      await clickButton(ctx, LABEL, "menu");
      await sleep(800);
      await ctx.client.evaluate(`window.__dgEd.selectNone(); return true;`);
      await sleep(300);
      await fr.add("done", 3);
      const frames = fr.done();
      return { frames, after, end: await observe(ctx) };
