// Shared helpers for ENG-2360 "Discourse nodes" docs recaptures (slot 3).
import fs from "node:fs";

export const DIR = "_verify/eng-2360-document-canvas-relation-type-creation-for-unconfigured-node";
export const CANVAS_NAME = "Sleep and memory.md";
export const CANVAS = `${DIR}/${CANVAS_NAME}`;
export const NOTE_NAME = "Sleep reading notes.md";
export const NOTE = `${DIR}/${NOTE_NAME}`;
export const OUT = new URL("./", import.meta.url).pathname;
export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
export const P = (ctx) => `app.plugins.plugins[${ctx.json(ctx.vault.pluginId)}]`;

export const TYPES = {
  Question: "node_XCu27P2XQr25v3U11jtp_",
  Claim: "REDACTED",
  Evidence: "node_jB6xyEvdVNLiZnGEbeKoy",
  Source: "node_1sOWrwNwBg-XtWq7Gb0lW",
};

export const FIXTURES = [
  ["QUE - What drives memory consolidation during sleep", "Question"],
  ["QUE - Does napping improve learning", "Question"],
  ["CLM - Slow-wave sleep strengthens new memories", "Claim"],
  ["CLM - REM sleep supports emotional memory", "Claim"],
  ["CLM - Sleep spindles predict overnight recall", "Claim"],
  ["EVD - Recall improved after a full night of sleep", "Evidence"],
  ["EVD - Sleep deprivation reduced hippocampal activity", "Evidence"],
  ["EVD - Targeted memory reactivation boosted retention", "Evidence"],
  ["SRC - Walker 2017 - Why we sleep", "Source"],
  ["SRC - Diekelmann and Born 2010", "Source"],
];

const CANVAS_BODY = (uuid) => `---
tldr-dg: true
---


\`\`\`json !!!_START_OF_TLDRAW_DG_DATA__DO_NOT_CHANGE_THIS_PHRASE_!!!
{
	"meta": { "uuid": "${uuid}", "plugin-version": "1.5.2", "tldraw-version": "3.14.2" },
	"raw": {
		"tldrawFileFormatVersion": 1,
		"schema": { "schemaVersion": 2, "sequences": {
			"com.tldraw.store": 4, "com.tldraw.asset": 1, "com.tldraw.camera": 1, "com.tldraw.document": 2,
			"com.tldraw.instance": 25, "com.tldraw.instance_page_state": 5, "com.tldraw.page": 1,
			"com.tldraw.instance_presence": 6, "com.tldraw.pointer": 1, "com.tldraw.shape": 4,
			"com.tldraw.asset.bookmark": 2, "com.tldraw.asset.image": 5, "com.tldraw.asset.video": 5,
			"com.tldraw.shape.arrow": 6, "com.tldraw.shape.bookmark": 2, "com.tldraw.shape.draw": 2,
			"com.tldraw.shape.embed": 4, "com.tldraw.shape.frame": 1, "com.tldraw.shape.geo": 10,
			"com.tldraw.shape.group": 0, "com.tldraw.shape.highlight": 1, "com.tldraw.shape.image": 5,
			"com.tldraw.shape.line": 5, "com.tldraw.shape.note": 9, "com.tldraw.shape.text": 3,
			"com.tldraw.shape.video": 4, "com.tldraw.binding.arrow": 1 } },
		"records": []
	}
}
!!!_END_OF_TLDRAW_DG_DATA__DO_NOT_CHANGE_THIS_PHRASE_!!!
\`\`\`
`;

const NOTE_BODY = `# Sleep reading notes

Walker argues that the night after learning matters as much as the learning itself.

- Main claim: [[CLM - Slow-wave sleep strengthens new memories]]
- Supporting result: [[EVD - Recall improved after a full night of sleep]]
- Open question: [[QUE - What drives memory consolidation during sleep]]
`;

// Writes fixtures and a fresh empty canvas; waits for the metadata cache to see nodeTypeId.
export const writeFixtures = async (ctx) => {
  for (const [name, type] of FIXTURES) {
    await ctx.writeNote(`${name}.md`, `---\nnodeTypeId: ${TYPES[type]}\n---\n\n${name.replace(/^\w+ - /, "")}.\n`);
  }
  await ctx.writeNote(NOTE_NAME, NOTE_BODY);
  await ctx.writeNote(CANVAS_NAME, CANVAS_BODY(crypto.randomUUID()));
  await ctx.client.waitFor(
    `return ${ctx.json(FIXTURES.map(([n]) => `${DIR}/${n}.md`))}.every((p) => { const f = app.vault.getAbstractFileByPath(p); return !!(f && app.metadataCache.getFileCache(f)?.frontmatter?.nodeTypeId); });`,
    { timeout: 10000, label: "fixture metadata" },
  );
};

// In-memory: only the four realistic node types, "claim" shown as "Claim". Returns a restore snapshot.
export const tidySettings = async (ctx) => {
  const snap = await ctx.client.evaluate(`return JSON.stringify(${P(ctx)}.settings.nodeTypes);`);
  await ctx.client.evaluate(`const st = ${P(ctx)}.settings;
    const keep = new Set(${ctx.json(Object.values(TYPES))});
    st.nodeTypes = st.nodeTypes.filter((n) => keep.has(n.id)).map((n) => n.name === "claim" ? { ...n, name: "Claim" } : n);
    return true;`);
  return snap;
};
export const restoreSettings = (ctx, snap) =>
  snap && ctx.client.evaluate(`${P(ctx)}.settings.nodeTypes = JSON.parse(${ctx.json(snap)}); return true;`);

// Opens the canvas in `leaf` (or a new tab) and stores the tldraw editor at window.__dgEd.
export const openCanvas = (ctx, leafExpr = `app.workspace.getLeaf("tab")`) =>
  ctx.client.evaluate(`return (async () => {
    let leaf = app.workspace.getLeavesOfType("tldraw-dg-preview").find((l) => l.view.file?.path === ${ctx.json(CANVAS)});
    if (!leaf) {
      leaf = ${leafExpr};
      await leaf.setViewState({ type: "tldraw-dg-preview", state: { file: ${ctx.json(CANVAS)} } });
    }
    app.workspace.setActiveLeaf(leaf, { focus: true });
    for (let i = 0; i < 40 && !leaf.view.containerEl.querySelector(".tl-canvas"); i++) await new Promise((r) => setTimeout(r, 100));
    await new Promise((r) => setTimeout(r, 300));
    const el = leaf.view.containerEl.querySelector(".tl-canvas");
    const k = Object.keys(el).find((k) => k.startsWith("__reactFiber"));
    let f = el[k];
    while (f) { const v = f.memoizedProps?.value; if (v?.store && v.getCurrentPageShapes) { window.__dgEd = v; break; } f = f.return; }
    window.__dgEd.selectNone();
    return true;
  })();`);

// Adds existing fixture nodes through the plugin's own obsidian:// URL handler.
export const addExisting = async (ctx, items) => {
  for (const [name, x, y] of items) {
    await ctx.client.evaluate(`const url = "obsidian://open?vault=" + encodeURIComponent(app.vault.getName()) + "&file=" + encodeURIComponent(${ctx.json(`${DIR}/${name}.md`)});
      window.__dgEd.putExternalContent({ type: "url", url, point: { x: ${x}, y: ${y} } }); return true;`);
    await sleep(700);
  }
  await ctx.client.evaluate(`window.__dgEd.selectNone(); return true;`);
};

export const nodeTitles = (ctx) =>
  ctx.client.evaluate(`return window.__dgEd.getCurrentPageShapes().filter((s) => s.type === "discourse-node").map((s) => ({ id: s.id, title: s.props.title, x: Math.round(s.x), y: Math.round(s.y), nodeTypeId: s.props.nodeTypeId }));`);

export const hideNotices = (ctx) => ctx.client.evaluate(`document.querySelectorAll(".notice").forEach((n) => n.remove()); return true;`);

export const rectOf = (ctx, js) =>
  ctx.client.evaluate(`const el = (() => { ${js} })(); if (!el) return null; const r = el.getBoundingClientRect(); return { x: r.left, y: r.top, width: r.width, height: r.height, cx: r.left + r.width / 2, cy: r.top + r.height / 2 };`);

export const mouse = (client, type, x, y, extra = {}) =>
  client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1, ...extra });

export const clickAt = async (client, x, y) => {
  await mouse(client, "mouseMoved", x, y, { button: "none" });
  await sleep(60);
  await mouse(client, "mousePressed", x, y, { buttons: 1 });
  await mouse(client, "mouseReleased", x, y);
  await sleep(250);
};

// Frame recorder clipped to a fixed CSS-px rect; writes PNGs plus an ffmpeg concat list.
export const recorder = (ctx, name, clip) => {
  const dir = `${OUT}frames/${name}/`;
  fs.rmSync(dir, { recursive: true, force: true });
  fs.mkdirSync(dir, { recursive: true });
  let n = 0;
  const list = [];
  return {
    async add(dur) {
      const f = `f${String(++n).padStart(3, "0")}.png`;
      await hideNotices(ctx);
      const { data } = await ctx.client.send("Page.captureScreenshot", { format: "png", clip: { ...clip, scale: 1 } });
      fs.writeFileSync(dir + f, Buffer.from(data, "base64"));
      list.push(`file '${f}'\nduration ${dur}`);
    },
    done() {
      const last = list[list.length - 1].split("\n")[0];
      fs.writeFileSync(dir + "list.txt", list.join("\n") + "\n" + last + "\n");
      return n;
    },
  };
};

// Second CDP session on the same page so we can receive Input.dragIntercepted events.
export const sideSession = async (ctx) => {
  const targets = await (await fetch("http://127.0.0.1:9222/json/list")).json();
  const uuid = await ctx.client.evaluate(`return (window.__dgSideId ??= crypto.randomUUID());`);
  for (const t of targets.filter((t) => t.type === "page" && !t.url.startsWith("devtools://"))) {
    const s = await openWs(t.webSocketDebuggerUrl);
    const r = await s.send("Runtime.evaluate", { expression: "window.__dgSideId", returnByValue: true }).catch(() => null);
    if (r?.result?.value === uuid) return s;
    s.close();
  }
  throw new Error("side session target not found");
};

const openWs = async (url) => {
  const ws = new WebSocket(url);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
  let id = 0;
  const pending = new Map();
  const listeners = new Map();
  ws.onmessage = (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      const p = pending.get(msg.id); pending.delete(msg.id);
      msg.error ? p.rej(new Error(JSON.stringify(msg.error))) : p.res(msg.result);
    } else if (msg.method) (listeners.get(msg.method) ?? []).forEach((fn) => fn(msg.params));
  };
  return {
    send: (method, params = {}) => new Promise((res, rej) => { const i = ++id; pending.set(i, { res, rej }); ws.send(JSON.stringify({ id: i, method, params })); }),
    once: (method, timeout = 3000) => new Promise((res, rej) => {
      const fn = (p) => { listeners.set(method, (listeners.get(method) ?? []).filter((f) => f !== fn)); clearTimeout(t); res(p); };
      const t = setTimeout(() => rej(new Error(`timeout ${method}`)), timeout);
      listeners.set(method, [...(listeners.get(method) ?? []), fn]);
    }),
    close: () => ws.close(),
  };
};

// Real-input HTML5 drag: press on `from`, move until Chromium intercepts the drag, then replay dragEnter/Over/drop toward `to`.
export const html5Drag = async (ctx, from, to, frames, steps = 14) => {
  const s = await sideSession(ctx);
  try {
    await s.send("Input.setInterceptDrags", { enabled: true });
    const m = (type, x, y, extra = {}) => s.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1, ...extra });
    const intercepted = s.once("Input.dragIntercepted", 4000);
    await m("mouseMoved", from.x, from.y, { button: "none" });
    await sleep(150);
    await m("mousePressed", from.x, from.y, { buttons: 1 });
    for (let i = 1; i <= 4; i++) { await m("mouseMoved", from.x + i * 4, from.y + i * 2, { buttons: 1 }); await sleep(30); }
    const { data } = await intercepted;
    let last = { x: from.x + 16, y: from.y + 8 };
    await s.send("Input.dispatchDragEvent", { type: "dragEnter", x: last.x, y: last.y, data });
    for (let i = 1; i <= steps; i++) {
      const t = i / steps;
      const ease = 1 - (1 - t) * (1 - t);
      last = { x: from.x + (to.x - from.x) * ease, y: from.y + (to.y - from.y) * ease };
      await m("mouseMoved", last.x, last.y, { buttons: 1 }).catch(() => {});
      await s.send("Input.dispatchDragEvent", { type: "dragOver", x: last.x, y: last.y, data });
      await sleep(40);
      if (frames && i % 2 === 0) await frames.add(0.1);
    }
    await s.send("Input.dispatchDragEvent", { type: "drop", x: to.x, y: to.y, data });
    await m("mouseReleased", to.x, to.y).catch(() => {});
    return data;
  } finally {
    await s.send("Input.setInterceptDrags", { enabled: false }).catch(() => {});
    s.close();
  }
};

