// ENG-2360 docs GIF frames: create discourse node, file explorer drag, editor handle drag.
import {
  DIR, CANVAS, NOTE, TYPES, sleep, writeFixtures, tidySettings, restoreSettings, openCanvas,
  addExisting, nodeTitles, rectOf, clickAt, mouse, recorder, html5Drag, hideNotices,
} from "./lib.mjs";

const ONLY = process.env.DG_ONLY;
const NEW_TITLE = "Deep sleep replays the day's experiences";

const closeLeaves = (ctx) =>
  ctx.client.evaluate(`app.workspace.getLeavesOfType("tldraw-dg-preview").concat(app.workspace.getLeavesOfType("markdown"))
    .filter((l) => (l.view.file?.path ?? "").startsWith(${ctx.json(DIR)})).forEach((l) => l.detach()); return true;`);

const setup = async (ctx) => {
  const snap = await tidySettings(ctx);
  await closeLeaves(ctx);
  await sleep(300);
  await writeFixtures(ctx);
  return { snap };
};

const teardown = async (ctx, s) => {
  await ctx.client.clearModals?.();
  await restoreSettings(ctx, s?.snap);
  await ctx.client.evaluate(`return (async () => {
    for (const f of app.vault.getMarkdownFiles().filter((f) => f.basename === ${ctx.json("CLM - " + NEW_TITLE)} && !f.path.startsWith(${ctx.json(DIR)}))) await app.vault.trash(f, false);
    return true; })();`);
  await closeLeaves(ctx);
};

const canvasClip = async (ctx) => {
  const r = await rectOf(ctx, `return window.__dgEd.getContainer();`);
  return { x: r.x, y: r.y, width: r.width, height: r.height };
};

const visible = (sel) => `return [...document.querySelectorAll(${JSON.stringify(sel)})].find((e) => e.getBoundingClientRect().width > 0);`;

const createNode = {
  name: "create-discourse-node",
  input: "toolbar Discourse Graph → Claim → click canvas → type title → Confirm",
  expected: "new Claim card on canvas",
  setup,
  run: async (ctx) => {
    await ctx.client.evaluate(`app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse(); return true;`);
    await openCanvas(ctx);
    await sleep(400);
    await addExisting(ctx, [
      ["QUE - What drives memory consolidation during sleep", 80, 80],
      ["EVD - Recall improved after a full night of sleep", 80, 420],
    ]);
    await ctx.client.evaluate(`window.__dgEd.setCamera({ x: 40, y: 40, z: 1 }, { immediate: true }); return true;`);
    await sleep(500);
    const clip = await canvasClip(ctx);
    const fr = recorder(ctx, "create-discourse-node", clip);
    await fr.add(1.2);
    const tool = await rectOf(ctx, visible(`[data-testid="tools.discourse-node"]`));
    await clickAt(ctx.client, tool.cx, tool.cy);
    await ctx.client.waitFor(`!!document.querySelector("[data-dg_node_type_id]")`, { label: "node type panel" });
    await sleep(300);
    await fr.add(1.5);
    const claim = await rectOf(ctx, `return document.querySelector('[data-dg_node_type_id="${TYPES.Claim}"]');`);
    await clickAt(ctx.client, claim.cx, claim.cy);
    await sleep(300);
    await fr.add(1.5);
    const target = { x: clip.x + clip.width * 0.62, y: clip.y + clip.height * 0.33 };
    await clickAt(ctx.client, target.x, target.y);
    await ctx.client.waitFor(`!!document.querySelector(".modal-container textarea")`, { label: "create modal" });
    await sleep(500);
    await fr.add(1.8);
    const ta = await rectOf(ctx, `return document.querySelector(".modal-container textarea");`);
    await clickAt(ctx.client, ta.cx, ta.cy);
    for (let i = 0; i < NEW_TITLE.length; i++) {
      await ctx.client.typeText(NEW_TITLE[i]);
      if (i % 5 === 4) await fr.add(0.1);
    }
    await sleep(700);
    await fr.add(2);
    const modal = await ctx.client.evaluate(`const m = document.querySelector(".modal-container");
      return { title: m.querySelector("h2")?.textContent, labels: [...m.querySelectorAll(".setting-item-name")].map((e) => e.textContent), type: m.querySelector("select")?.selectedOptions[0]?.textContent,
        buttons: [...m.querySelectorAll("button")].map((b) => b.textContent.trim()).filter(Boolean), placeholder: m.querySelector("textarea")?.placeholder,
        popover: m.querySelector(".suggestion-container")?.textContent ?? document.querySelector(".suggestion-container")?.textContent ?? null };`);
    const confirm = await rectOf(ctx, `return [...document.querySelectorAll(".modal-container button")].find((b) => b.textContent.trim() === "Confirm");`);
    await clickAt(ctx.client, confirm.cx, confirm.cy);
    await ctx.client.waitFor(`!document.querySelector(".modal-container")`, { label: "modal closed", timeout: 8000 });
    await sleep(1500);
    await fr.add(1.5);
    await ctx.client.evaluate(`window.__dgEd.selectNone(); return true;`);
    await sleep(300);
    await fr.add(3);
    return { frames: fr.done(), modal, nodes: await nodeTitles(ctx), toolLabel: await ctx.client.evaluate(visible(`[data-testid="tools.discourse-node"]`).replace("return ", "return (") + ")?.getAttribute('aria-label') ?? null") };
  },
  expect: (o) => ({ pass: o.nodes.some((n) => n.title.includes(NEW_TITLE)), actual: JSON.stringify(o) }),
  teardown,
};

const explorerDrag = {
  name: "file-explorer-drag",
  input: "drag CLM note row from file explorer onto canvas",
  expected: "Claim card at drop point",
  setup,
  run: async (ctx) => {
    await ctx.client.evaluate(`app.workspace.rightSplit.collapse(); app.workspace.leftSplit.expand(); return true;`);
    await openCanvas(ctx);
    await addExisting(ctx, [["QUE - What drives memory consolidation during sleep", 60, 60]]);
    await ctx.client.evaluate(`window.__dgEd.setCamera({ x: 0, y: 0, z: 1 }, { immediate: true }); return true;`);
    // Reveal the fixture folder, collapse other folders, scroll fixtures to the top of the tree.
    await ctx.client.evaluate(`return (async () => {
      const fe = app.workspace.getLeavesOfType("file-explorer")[0];
      app.workspace.leftSplit.expand(); app.workspace.revealLeaf(fe);
      const v = fe.view;
      for (const [p, item] of Object.entries(v.fileItems)) if (item.setCollapsed && p !== "/" ) item.setCollapsed(!(p === "_verify" || p === ${ctx.json(DIR)}), false);
      v.revealInFolder(app.vault.getAbstractFileByPath(${ctx.json(CANVAS)}));
      await new Promise((r) => setTimeout(r, 400));
