const ARROW = `<svg xmlns="http://www.w3.org/2000/svg" width="22" height="28" viewBox="0 0 22 28"><path d="M2 2 L2 22 L7.5 17 L11 26 L14.5 24.5 L11 15.8 L18.5 15.8 Z" fill="black" stroke="white" stroke-width="1.6" stroke-linejoin="round"/></svg>`;

// Screenshots omit the OS cursor; draw one (tip at its top-left + 2px) so viewers can follow the pointer.
export const cursorAt = (ctx, p) =>
  ctx.client.evaluate(`let c = document.getElementById("dg-doc-cursor");
    if (!c) { c = document.createElement("div"); c.id = "dg-doc-cursor";
      c.style.cssText = "position:fixed;z-index:2147483647;pointer-events:none;left:0;top:0;width:22px;height:28px;";
      c.innerHTML = ${JSON.stringify(ARROW)}; document.body.appendChild(c); }
    c.style.transform = "translate(" + (${p.x} - 2) + "px," + (${p.y} - 2) + "px)"; return true;`);
export const removeCursor = (ctx) => ctx.client.evaluate(`document.getElementById("dg-doc-cursor")?.remove(); return true;`);

export const FRAME = 0.06;
const easeIO = (t) => (t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2);

// `send` dispatches mouse events (main or side session); `onStep` runs per frame (e.g. a dragOver).
export const human = (ctx, fr, start) => {
  let pos = start;
  let send = (type, p, extra = {}) =>
    ctx.client.send("Input.dispatchMouseEvent", { type, x: p.x, y: p.y, button: "left", clickCount: 1, ...extra });
  const moveTo = async (to, ms = 600, { buttons = 0, onStep } = {}) => {
    const steps = Math.max(2, Math.round(ms / 1000 / FRAME));
    const from = pos;
    for (let i = 1; i <= steps; i++) {
      const t = easeIO(i / steps);
      pos = { x: from.x + (to.x - from.x) * t, y: from.y + (to.y - from.y) * t };
      await send("mouseMoved", pos, buttons ? { buttons: 1 } : { button: "none" }).catch(() => {});
      if (onStep) await onStep(pos);
      await cursorAt(ctx, pos);
      await fr.add(FRAME);
    }
  };
  return {
    get pos() { return pos; },
    useSender(fn) { send = fn; },
    moveTo,
    async hold(sec) { await cursorAt(ctx, pos); await fr.add(sec); },
    async click(to, { ms = 600, after = 0.5 } = {}) {
      await moveTo(to, ms);
      await fr.add(0.2);
      await send("mousePressed", pos, { buttons: 1 });
      await send("mouseReleased", pos);
      await sleep(350);
      await cursorAt(ctx, pos);
      await fr.add(after);
    },
    async type(text, perChar = 0.11) {
      for (const ch of text) { await ctx.client.typeText(ch); await fr.add(perChar); }
    },
  };
};

// HTML5 drag at human speed: real press + small move until Chromium intercepts, then eased dragOver per frame.
export const humanHtml5Drag = async (ctx, h, to, ms = 1100) => {
  const s = await sideSession(ctx);
  const send = (type, p, extra = {}) => s.send("Input.dispatchMouseEvent", { type, x: p.x, y: p.y, button: "left", clickCount: 1, ...extra });
  try {
    await s.send("Input.setInterceptDrags", { enabled: true });
    const intercepted = s.once("Input.dragIntercepted", 4000);
    const p0 = h.pos;
    await send("mouseMoved", p0, { button: "none" });
    await send("mousePressed", p0, { buttons: 1 });
    for (let i = 1; i <= 3; i++) { await send("mouseMoved", { x: p0.x + i * 2, y: p0.y + i }, { buttons: 1 }); await sleep(30); }
    const { data } = await intercepted;
    await s.send("Input.dispatchDragEvent", { type: "dragEnter", x: p0.x + 6, y: p0.y + 3, data });
    h.useSender(send);
    await h.moveTo(to, ms, { buttons: 1, onStep: (p) => s.send("Input.dispatchDragEvent", { type: "dragOver", x: p.x, y: p.y, data }) });
    await s.send("Input.dispatchDragEvent", { type: "drop", x: to.x, y: to.y, data });
    await send("mouseReleased", to).catch(() => {});
    return data;
  } finally {
    h.useSender((type, p, extra = {}) => ctx.client.send("Input.dispatchMouseEvent", { type, x: p.x, y: p.y, button: "left", clickCount: 1, ...extra }));
    await s.send("Input.setInterceptDrags", { enabled: false }).catch(() => {});
    s.close();
  }
};
'''
open(p,'w').write(s)
EOF
