// ENG-2360 docs GIFs at human speed: create discourse node, file explorer drag, editor handle drag.
import {
  DIR, CANVAS, NOTE, TYPES, FIXTURES, sleep, writeFixtures, tidySettings, restoreSettings, openCanvas,
  addExisting, nodeTitles, rectOf, recorder, human, humanHtml5Drag, removeCursor,
} from "./lib.mjs";

const ONLY = process.env.DG_ONLY;
const NEW_TITLE = "Deep sleep replays the day's experiences";
const CLM = "CLM - Slow-wave sleep strengthens new memories";

const closeLeaves = (ctx) =>
  ctx.client.evaluate(`app.workspace.getLeavesOfType("tldraw-dg-preview").concat(app.workspace.getLeavesOfType("markdown"))
    .filter((l) => (l.view.file?.path ?? "").startsWith(${ctx.json(DIR)})).forEach((l) => l.detach()); return true;`);

const setup = async (ctx) => {
  const snap = await tidySettings(ctx);
  await closeLeaves(ctx);
  await sleep(300);
  await writeFixtures(ctx);
  return { snap };
};

const teardown = async (ctx, s) => {
  await removeCursor(ctx);
  await ctx.client.clearModals?.();
  await restoreSettings(ctx, s?.snap);
  await ctx.client.evaluate(`return (async () => {
    for (const f of app.vault.getMarkdownFiles().filter((f) => f.basename === ${ctx.json("CLM - " + NEW_TITLE)} && !f.path.startsWith(${ctx.json(DIR)}))) await app.vault.trash(f, false);
    return true; })();`);
  await closeLeaves(ctx);
};

const canvasRect = (ctx) => rectOf(ctx, `return window.__dgEd.getContainer();`);
const clipOf = (r) => ({ x: r.x, y: r.y, width: r.width, height: r.height });
const visibleSel = (sel) => `return [...document.querySelectorAll(${JSON.stringify(sel)})].find((e) => e.getBoundingClientRect().width > 0);`;
const shapeScreen = (ctx, title) =>
  ctx.client.evaluate(`const ed = window.__dgEd; const s = ed.getCurrentPageShapes().find((s) => s.props?.title?.startsWith(${ctx.json(title)}));
    if (!s) return null; const b = ed.getShapePageBounds(s.id); const tl = ed.pageToScreen({ x: b.minX, y: b.minY }), br = ed.pageToScreen({ x: b.maxX, y: b.maxY });
    return { l: tl.x, t: tl.y, r: br.x, b: br.y };`);

// Move the cursor clear of the card, then hold the final frame.
const finish = async (ctx, fr, h, away) => {
  await ctx.client.evaluate(`window.__dgEd.selectNone(); return true;`);
  await h.moveTo(away, 600);
  await h.hold(3);
  return fr.done();
};

const createNode = {
  name: "create-discourse-node",
  input: "toolbar Discourse Graph → Claim → click canvas → type title → Confirm",
  expected: "new Claim card on canvas",
  setup,
  run: async (ctx) => {
    await ctx.client.evaluate(`app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse(); return true;`);
    await openCanvas(ctx);
    await sleep(400);
    await addExisting(ctx, [
      ["QUE - What drives memory consolidation during sleep", 80, 80],
      ["EVD - Recall improved after a full night of sleep", 80, 420],
    ]);
    await ctx.client.evaluate(`window.__dgEd.setCamera({ x: 30, y: 20, z: 1.25 }, { immediate: true }); return true;`);
    await sleep(500);
    const c = await canvasRect(ctx);
    const fr = recorder(ctx, "create-discourse-node", clipOf(c));
    const h = human(ctx, fr, { x: c.x + c.width * 0.45, y: c.y + c.height * 0.6 });
    await h.hold(1.2);
    const tool = await rectOf(ctx, visibleSel(`[data-testid="tools.discourse-node"]`));
    await h.click({ x: tool.cx, y: tool.cy }, { ms: 700, after: 0.3 });
    await ctx.client.waitFor(`!!document.querySelector("[data-dg_node_type_id]")`, { label: "node type panel" });
    await sleep(300);
    await h.hold(1.3);
    const claim = await rectOf(ctx, `return document.querySelector('[data-dg_node_type_id="${TYPES.Claim}"]');`);
    await h.click({ x: claim.cx, y: claim.cy }, { ms: 900, after: 1.0 });
    await h.click({ x: c.x + c.width * 0.6, y: c.y + c.height * 0.33 }, { ms: 800, after: 0.2 });
    await ctx.client.waitFor(`!!document.querySelector(".modal-container textarea")`, { label: "create modal" });
    await sleep(400);
    await h.hold(1.5);
    const ta = await rectOf(ctx, `return document.querySelector(".modal-container textarea");`);
    await h.click({ x: ta.x + 60, y: ta.cy }, { ms: 500, after: 0.3 });
    await h.type(NEW_TITLE);
    await sleep(500);
    await h.hold(1.5);
    const modal = await ctx.client.evaluate(`const m = document.querySelector(".modal-container");
      return { title: m.querySelector("h2")?.textContent, labels: [...m.querySelectorAll(".setting-item-name")].map((e) => e.textContent), type: m.querySelector("select")?.selectedOptions[0]?.textContent,
        buttons: [...m.querySelectorAll("button")].map((b) => b.textContent.trim()).filter(Boolean) };`);
    const confirm = await rectOf(ctx, `return [...document.querySelectorAll(".modal-container button")].find((b) => b.textContent.trim() === "Confirm");`);
    await h.click({ x: confirm.cx, y: confirm.cy }, { ms: 600, after: 0.1 });
    await ctx.client.waitFor(`!document.querySelector(".modal-container")`, { label: "modal closed", timeout: 8000 });
    await sleep(1200);
    await h.hold(1.8);
    const card = await shapeScreen(ctx, "CLM - Deep");
    const frames = await finish(ctx, fr, h, { x: card.l + 40, y: card.b + 150 });
    return { frames, modal, nodes: await nodeTitles(ctx) };
  },
  expect: (o) => ({ pass: o.nodes.some((n) => n.title.includes(NEW_TITLE)), actual: JSON.stringify({ frames: o.frames, modal: o.modal, nodes: o.nodes.map((n) => n.title) }) }),
  teardown,
};

