    const lastRow = await rectOf(ctx, `const rows = [...app.workspace.getLeavesOfType("file-explorer")[0].view.fileItems[${ctx.json(DIR)}].childrenEl.querySelectorAll(".tree-item-self")]; return rows[rows.length - 1];`);
    const clip = { x: nav.x, y: nav.y, width: c.x - nav.x + 600, height: lastRow.y + lastRow.height + 6 - nav.y };
    const fr = recorder(ctx, "file-explorer-drag", clip);
    const h = human(ctx, fr, { x: c.x + 300, y: c.y + clip.height - 60 });
    await h.hold(1.2);
    const row = await rectOf(ctx, `return app.workspace.getLeavesOfType("file-explorer")[0].view.fileItems[${ctx.json(`${DIR}/${CLM}.md`)}].selfEl;`);
    await h.moveTo({ x: row.x + 90, y: row.cy }, 800);
    await h.hold(0.8);
    const drop = { x: c.x + 170, y: c.y + Math.min(250, clip.height - 120) };
