      return [...s.querySelectorAll(".tree-item-self")].filter((e) => { const r = e.getBoundingClientRect(); return r.height && r.bottom > top && r.top < bot; }).map((e) => e.textContent.trim());`);
    return { frames, items: data.items.map((i) => i.mimeType), nodes, dropPage: await ctx.client.evaluate(`return window.__dgEd.screenToPage(${ctx.json(drop)});`), visibleRows, sortedFixtures: sorted.length };
  },
  expect: (o) => ({ pass: o.nodes.some((n) => n.title.startsWith(CLM)), actual: JSON.stringify({ ...o, nodes: o.nodes.map((n) => `${n.title}@${n.x},${n.y}`) }) }),
  teardown,
};

const editorDrag = {
  name: "editor-drag-node",
  input: "note (Live Preview) beside canvas; drag ⠿ after [[CLM …]] onto canvas",
  expected: "Claim card at drop point",
