fs.writeFileSync(dir + "sheet.txt", pick.map((f) => `file '${f}'`).join("\n") + "\n");
ff("-f", "concat", "-safe", "0", "-i", dir + "sheet.txt", "-vf", "scale=400:-1,tile=4x6", "-frames:v", "1", `${here}frames/sheet-${name}.png`);
